insert into ponew values
(1, 1, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Single-use items such as syringes and sutures are usually sterilised by the manufacturer using:', '["Dry heat ovens", "Boiling water", "Gamma irradiation", "Formaldehyde fumigation"]'::jsonb, 2, 'Single-use items must not be reprocessed or reused.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 2, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Which antiseptic should NOT be used near the eyes or middle ear?', '["Sterile water", "Povidone-iodine 5% (ophthalmic)", "Chlorhexidine", "Sterile normal saline"]'::jsonb, 2, 'Chlorhexidine can damage the cornea and cause deafness; dilute povidone-iodine is used for eyes.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 3, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'For skin preparation of a clean abdominal incision, the antiseptic is applied:', '["From the outer edges inward, finishing at the incision site", "In random strokes over the whole abdomen", "From the periphery inward toward the incision", "From the incision site outward toward the periphery"]'::jsonb, 3, 'Do not return to the clean centre with a used swab.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 4, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Before positioning a patient prone, the nurse must ensure:', '["The head is turned to one side and allowed to rest on the eye and cheek", "Breasts and genitals are compressed beneath the patient", "Supports leave the abdomen free and nothing presses on the eyes", "The arms are fully extended above 135 degrees overhead"]'::jsonb, 2, 'Pressure on the eye can cause blindness from retinal artery occlusion.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 5, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A suture described as ''2-0'' compared with ''4-0'' is:', '["Thicker", "Only used for skin", "Thinner", "The same thickness but absorbable"]'::jsonb, 0, 'The more zeros, the finer the suture; 6-0 is very fine, 1 is thick.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 6, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A tissue specimen for routine histology is placed in:', '["Alcohol hand rub, enough to cover the tissue", "Sterile water only, in a small sealed pot so the tissue stays fresh", "Normal saline in a dry, unlabelled container", "10% formalin, about 10 times the specimen''s volume"]'::jsonb, 3, 'Label with patient details, specimen site, date and the doctor''s name.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 7, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Who obtains informed consent for an operation?', '["The doctor doing the procedure, or a trained delegate", "Any family member who is present on the ward", "The anaesthetic nurse alone, before induction", "The theatre porter who brings the patient from the ward to theatre"]'::jsonb, 0, 'The nurse may witness the signature and check understanding.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 8, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A swab count discrepancy remains after a full search. The next step is usually:', '["Ignore it if the surgeon agrees to continue, and record the count as correct", "Ask the patient to return in 6 weeks for review", "Close the wound and document ''count correct''", "An intraoperative X-ray before the patient leaves theatre"]'::jsonb, 3, 'Surgical swabs have radio-opaque markers so they show on X-ray.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 9, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A round-bodied (taper-point) needle is preferred for:', '["Soft tissue such as bowel, where minimal cutting is wanted", "Thick skin that is hard to penetrate", "Bone and very tough fascia, where strong cutting edges are needed", "Tendons and ligaments in the hand only"]'::jsonb, 0, 'Cutting needles are used for skin; round-bodied needles part tissue without cutting it.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 10, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Nail polish and acrylic nails should be removed before surgery mainly because they:', '["Interfere with pulse oximetry and hide cyanosis", "Are flammable when diathermy is used near the hands and fingers", "Increase the risk of deep vein thrombosis", "Cause allergy to the anaesthetic drugs used"]'::jsonb, 0, 'Also inspect the nail beds for capillary refill.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 11, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A pneumatic tourniquet is contraindicated in a limb with:', '["Normal, strong peripheral pulses", "A planned skin graft on the limb, as the tourniquet damages grafts", "Severe peripheral vascular disease or known DVT", "A simple closed fracture of the leg"]'::jsonb, 2, 'Use is also avoided in sickle cell disease, unless the team agrees it is justified.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 12, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A typical intra-abdominal pressure limit during adult laparoscopy is:', '["100 mmHg", "40–50 mmHg", "2–3 mmHg", "12–15 mmHg"]'::jsonb, 3, 'Higher pressures reduce venous return and ventilation.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 13, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'In the beach-chair (sitting) position for shoulder surgery, a key risk is:', '["Raised intra-abdominal pressure", "Pressure ulcers on the face", "Brachial plexus injury from the arm board only", "Low cerebral perfusion if blood pressure falls"]'::jsonb, 3, 'Measure BP at heart and head level and avoid hypotension.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 14, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A ''neutral zone'' for sharps in theatre means:', '["Sharps are placed in a set area, not passed hand to hand", "The surgeon keeps all the needles in one hand so they are never dropped", "Sharps are left anywhere on the drapes to save time", "Needles are recapped before being passed back"]'::jsonb, 0, 'This hands-free technique reduces needlestick injuries.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 15, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Delayed primary closure (healing by third intention) is used when:', '["A clean wound is closed immediately in theatre", "A wound is left open to heal completely from the base by granulation", "Only a skin graft can close the remaining defect", "A contaminated wound is left open for a few days, then closed"]'::jsonb, 3, 'It lowers infection risk in dirty wounds.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 16, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Theatre nurses should report a near miss (an error that did not reach the patient) because:', '["It is used to identify and discipline the nurse who made the mistake", "It is only needed if real harm occurred", "It helps the team learn and prevent future harm", "It replaces the normal clinical documentation"]'::jsonb, 2, 'Near misses show weaknesses in the system.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 17, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Monofilament sutures have a lower infection risk than braided ones because they:', '["Are coated with an antibiotic layer", "Have no gaps where bacteria can hide", "Are always absorbable, so no foreign material stays in the body", "Are thicker and stronger than braids"]'::jsonb, 1, 'Braided sutures can ''wick'' bacteria, but they handle and knot more easily.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 18, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Shoulder-tip pain after laparoscopy is due to:', '["A myocardial infarction during surgery", "A diathermy burn on the shoulder skin", "Brachial plexus stretch from the arm boards", "Residual CO₂ irritating the diaphragm"]'::jsonb, 3, 'Referred to C3–C5; it settles in 1–3 days.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 19, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Implants used in surgery are recorded in the patient''s notes mainly to:', '["Allow tracing of the device if it is recalled", "Calculate the surgeon''s fee for the case", "Check that the steriliser cycle worked correctly for that tray", "Count the instruments at the end of the case"]'::jsonb, 0, 'Record the batch/lot and serial numbers.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 20, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Allis forceps have small teeth and are used to:', '["Grasp tissue firmly, such as fascia or bowel to be removed", "Cut sutures and fine dressings at the end of a case", "Hold curved needles firmly during suturing of skin", "Clamp the aorta gently without causing any damage to the vessel wall"]'::jsonb, 0, 'They are traumatic, so not used on tissue to be kept intact.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 21, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A scrub nurse notices a hole in her glove during a case. She should:', '["Put a second glove over the damaged glove and continue scrubbed in", "Step back from the field and have the glove changed", "Continue and change the glove at the very end", "Cover the hole with a piece of adhesive tape"]'::jsonb, 1, 'The circulating nurse removes the outer glove; the gown cuff must not be contaminated.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 22, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'The most effective active warming method during surgery is usually:', '["Extra cotton sheets only", "Warm fluids given orally", "A forced-air warming blanket", "Raising the room temperature to 35 °C"]'::jsonb, 2, 'Also warm IV and irrigation fluids and keep the patient covered.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 23, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Theatre clinical waste contaminated with blood is placed in:', '["The black general (domestic) waste bag", "The paper and plastic recycling bin near the theatre doors", "The infectious waste bag (usually yellow)", "The rigid sharps box beside the table"]'::jsonb, 2, 'Sharps go in rigid puncture-proof containers.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 24, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Bone wax is used during surgery to:', '["Join two fractured bone ends together", "Control bleeding from cut bone surfaces", "Seal cerebrospinal fluid leaks in the spine", "Lubricate surgical instruments"]'::jsonb, 1, 'It acts as a physical barrier; excess can delay bone healing.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 25, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Irrigation fluids used in a body cavity should be:', '["At room temperature from the store", "Chilled to reduce bleeding", "Warmed to body temperature", "Boiling hot to sterilise the cavity"]'::jsonb, 2, 'Cold fluids worsen hypothermia.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 26, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'When preparing skin around a stoma or the perineum, these ''dirty'' areas are cleaned:', '["Last, after the cleaner surrounding area", "First, before the surrounding skin, so that they are cleaned properly", "Never, as these areas cannot be cleaned", "First, before the surrounding skin"]'::jsonb, 0, 'This avoids carrying organisms onto clean skin.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 27, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Which observation by the circulating nurse is a break in sterile technique?', '["Two scrubbed people pass each other back to back", "A scrubbed person turns their back to the field", "The scrub nurse faces the sterile field at all times", "Scrubbed staff keep their hands above waist level"]'::jsonb, 1, 'The back of the gown is not sterile.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 28, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A pregnancy test before elective surgery in women of childbearing age is done mainly because:', '["It replaces the need for a separate signed consent form", "Anaesthesia, X-rays and surgery may harm an unknown pregnancy", "Pregnancy shortens the operation and the recovery time needed afterwards", "It is needed to calculate all the anaesthetic drug doses"]'::jsonb, 1, 'Follow local policy and respect patient choice.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 29, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Low-temperature hydrogen peroxide gas plasma sterilisation is useful because it:', '["It can sterilise linen, paper wraps and liquids very well, unlike steam", "It is cheaper and faster than steam for all types of items", "It sterilises heat- and moisture-sensitive items without toxic residue", "It leaves a protective chemical coating on the instruments"]'::jsonb, 2, 'Cellulose (paper, linen) and liquids cannot be processed in plasma systems.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 30, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'When the surgeon asks for local anaesthetic, the scrub nurse should:', '["Ask the patient which drug they prefer and draw it up without checking", "Draw it up without checking, as the surgeon will check", "Use any open bottle from the previous case", "Show the ampoule and confirm the drug, strength and dose aloud"]'::jsonb, 3, 'All drugs on the sterile field must be labelled.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 31, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A sterile instrument drops onto the floor during surgery. The correct action is to:', '["Return it if it was on the floor under a minute", "Treat it as contaminated and replace it if needed", "Rinse it in sterile water and carry on using it", "Wipe it with alcohol and return it to the tray if it looks clean"]'::jsonb, 1, 'If it cannot be replaced, it is reprocessed by an approved rapid cycle.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 32, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'The ''sterile cockpit'' or no-interruption rule in theatre applies particularly during:', '["Cleaning between cases and restocking of the theatre", "Ordering supplies from the store", "Lunch breaks and rest periods", "Counts, Time Out and critical steps of the operation"]'::jsonb, 3, 'Distractions cause errors in counts and checks.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 33, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A sterile pack is found with a water stain on its wrapper. The nurse should:', '["Use it after wiping the wrapper with alcohol", "Use it if the stain is dry and the tape has changed colour", "Consider it unsterile and send it for reprocessing", "Use it only for clean (not sterile) procedures"]'::jsonb, 2, 'Moisture wicks bacteria through the wrapper (strike-through).', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 34, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Before a patient leaves the anaesthetic room for theatre, the anaesthetic nurse confirms:', '["Monitoring, IV access and airway are secure", "The theatre has been terminally cleaned", "The patient has eaten breakfast", "The surgeon has finished the previous case notes"]'::jsonb, 0, 'Transfer is a high-risk time for disconnection.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 35, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'The correct order of instrument reprocessing is:', '["Cleaning, inspection, packing, sterilisation, storage", "Packing, sterilisation, cleaning and storage", "Inspection, sterilisation, storage and cleaning", "Sterilisation, then cleaning, inspection, packing and storage"]'::jsonb, 0, 'Dirt protects microorganisms, so cleaning always comes first.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 36, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Dentures and loose teeth are checked before anaesthesia because they:', '["Increase the risk of hypothermia during long surgery", "Alter the fasting time needed before the anaesthetic", "Can be dislodged and block or be inhaled into the airway", "Interfere with the diathermy return plate and cause skin burns"]'::jsonb, 2, 'Record loose teeth and caps on the checklist.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 37, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'Cell salvage during surgery means:', '["Removing blood before surgery for later transfusion", "Giving donor blood that is stored inside the theatre", "Collecting, washing and returning the patient''s own blood", "Giving plasma expanders only, without any blood products at all"]'::jsonb, 2, 'It is often acceptable to Jehovah''s Witnesses and reduces donor blood use.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 38, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'In laparoscopic surgery, the abdomen is usually insufflated with:', '["Oxygen, so the bowel stays pink", "Carbon dioxide", "Nitrous oxide", "Room air"]'::jsonb, 1, 'CO₂ is non-flammable and quickly absorbed.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 39, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'The recommended operating room temperature for most adult surgery is about:', '["18–23 °C, with relative humidity of 40–60%", "28–32 °C, with relative humidity of 10–20%", "35–37 °C, with relative humidity of 70–80%", "10–14 °C, with relative humidity of 80–90% to limit bacterial growth"]'::jsonb, 0, 'Cold rooms cause patient hypothermia; dry air causes static, humid air encourages microbial growth.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 40, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 413 · Principles & Practice of Perioperative Nursing', 'A surgical site infection is less likely if the patient''s blood glucose during surgery is:', '["Kept very low, below 3 mmol/L, to starve bacteria in the wound", "Kept within a target range, avoiding hyperglycaemia", "Not checked at all during surgery", "Allowed to rise above 15 mmol/L"]'::jsonb, 1, 'High glucose impairs white cell function and healing.', 'PON 413 · Principles & Practice of Perioperative Nursing'),
(1, 41, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Which spinal nerves give rise to the cervical plexus?', '["C3–T3", "C1–C4", "C5–T1", "T1–T12"]'::jsonb, 1, 'The cervical plexus is formed by the anterior rami of C1–C4. C5–T1 form the brachial plexus.', 'PON 411 · Anatomy & Physiology'),
(1, 42, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Antibodies belong to which class of plasma proteins?', '["Alpha globulins", "Agglutinins", "Albumins", "Gamma globulins"]'::jsonb, 3, 'Antibodies (immunoglobulins) are gamma globulins.', 'PON 411 · Anatomy & Physiology'),
(1, 43, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Which structure connects the pharynx to the bronchi, serving as the main airway?', '["Trachea", "Aorta", "Oesophagus", "Ureter"]'::jsonb, 0, 'The trachea is the main airway connecting the larynx/pharynx above to the bronchi below, allowing air to pass to and from the lungs.', 'PON 411 · Anatomy & Physiology'),
(1, 44, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Negative feedback, as a mechanism of hormonal control, means that:', '["Rising hormone levels stimulate even more hormone release, with no limit", "Rising hormone/product levels suppress further release, keeping levels in a stable range", "Feedback only applies to the nervous system, never hormones", "Hormone levels are entirely independent of blood concentration"]'::jsonb, 1, 'Negative feedback is the most common hormonal regulation mechanism: rising levels of a hormone or its effect suppress further release, maintaining homeostasis.', 'PON 411 · Anatomy & Physiology'),
(1, 45, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The brain structure primarily responsible for coordinating balance and fine motor movement is the:', '["Cerebellum", "Thalamus", "Medulla oblongata", "Cerebrum"]'::jsonb, 0, 'The cerebellum coordinates balance, posture, and the fine-tuning of voluntary motor movements.', 'PON 411 · Anatomy & Physiology'),
(1, 46, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Most of the body cells'' energy is derived from chemical reactions, which can only take place in the presence of:', '["Oxygen", "Blood", "ATP", "Carbon dioxide"]'::jsonb, 0, 'Aerobic metabolism (oxidative phosphorylation) needs oxygen and produces most of the cell''s ATP.', 'PON 411 · Anatomy & Physiology'),
(1, 47, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The heart''s four chambers consist of:', '["Four atria only", "Four ventricles only", "Two atria and two ventricles", "One atrium and three ventricles"]'::jsonb, 2, 'The heart has two upper chambers (right and left atria) and two lower chambers (right and left ventricles).', 'PON 411 · Anatomy & Physiology'),
(1, 48, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Which cranial nerve is the motor nerve to the tongue muscles?', '["Hypoglossal nerve", "Glossopharyngeal nerve", "Oculomotor nerve", "Olfactory nerve"]'::jsonb, 0, 'The hypoglossal nerve (CN XII) is the motor nerve to the tongue muscles.', 'PON 411 · Anatomy & Physiology'),
(1, 49, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The functional unit of the kidney responsible for filtration is the:', '["Bladder trigone", "Nephron", "Ureter", "Renal pelvis"]'::jsonb, 1, 'The nephron, comprising the glomerulus and its associated tubules, is the kidney''s basic functional/filtering unit.', 'PON 411 · Anatomy & Physiology'),
(1, 50, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Gaseous exchange in the lungs occurs primarily at the level of the:', '["Trachea", "Alveoli", "Larynx", "Bronchi"]'::jsonb, 1, 'The alveoli, with their thin walls and rich capillary network, are the site of gas exchange between air and blood.', 'PON 411 · Anatomy & Physiology'),
(1, 51, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The levator ani muscle consists of how many muscles?', '["5", "4", "3", "2"]'::jsonb, 2, 'The levator ani has three parts: pubococcygeus, puborectalis and iliococcygeus.', 'PON 411 · Anatomy & Physiology'),
(1, 52, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The part of the ear that functions in both hearing and balance is the:', '["Inner ear", "Middle ear", "Eustachian tube", "Outer ear"]'::jsonb, 0, 'The inner ear holds the cochlea (hearing) and the vestibular apparatus (balance).', 'PON 411 · Anatomy & Physiology'),
(1, 53, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Heparin and histamine are secreted by:', '["Plasma cells", "Basophils", "B lymphocytes", "Neutrophils"]'::jsonb, 1, 'Basophils, like mast cells, secrete heparin and histamine.', 'PON 411 · Anatomy & Physiology'),
(1, 54, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The brainstem consists of:', '["Hindbrain, ventricle and pons", "Midbrain, pons and medulla", "Midbrain, pons and forebrain", "Midbrain, hindbrain and forebrain"]'::jsonb, 1, 'The brainstem consists of the midbrain, pons and medulla oblongata.', 'PON 411 · Anatomy & Physiology'),
(1, 55, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The approximate daily volume of glomerular filtrate in an adult is:', '["120 L in males and 130 L in females", "180 L in males and about 150 L in females", "50 L in males and 90 L in females", "300 L in both sexes"]'::jsonb, 1, 'The kidneys filter about 180 L of plasma a day (GFR about 125 mL/min) in adult men, slightly less in women.', 'PON 411 · Anatomy & Physiology'),
(1, 56, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'A deficiency of pulmonary surfactant is most likely to cause:', '["Atelectasis", "COPD", "Pneumothorax", "Chronic bronchitis"]'::jsonb, 0, 'Surfactant lowers alveolar surface tension. Without it, alveoli collapse (atelectasis), as in neonatal respiratory distress syndrome.', 'PON 411 · Anatomy & Physiology'),
(1, 57, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Which of the following cells are in almost constant mitosis?', '["Gastric epithelial cells", "Renal cells", "Nerve cells", "Skeletal muscle cells"]'::jsonb, 0, 'Epithelial lining cells, such as gastric and intestinal mucosa, renew constantly by mitosis. Neurons and cardiac and skeletal muscle rarely divide.', 'PON 411 · Anatomy & Physiology'),
(1, 58, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The olfactory tract terminates in which area of the brain?', '["Olfactory bulb", "Olfactory cortex", "Visual cortex", "Cribriform plate"]'::jsonb, 1, 'The olfactory tract carries impulses from the olfactory bulb to the primary olfactory cortex in the temporal lobe.', 'PON 411 · Anatomy & Physiology'),
(1, 59, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Clotting factors are primarily synthesised by the:', '["Pancreas", "Spleen", "Liver", "Kidneys"]'::jsonb, 2, 'Most clotting factors are synthesised in the liver, which is why liver disease can impair coagulation.', 'PON 411 · Anatomy & Physiology'),
(1, 60, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The largest air passages that take part in gas exchange are the:', '["Primary bronchi", "Alveolar ducts", "Terminal bronchioles", "Respiratory bronchioles"]'::jsonb, 3, 'Respiratory bronchioles are the first, and largest, airways with alveoli in their walls, where gas exchange begins.', 'PON 411 · Anatomy & Physiology'),
(1, 61, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The layer of the heart responsible for its pumping contraction is the:', '["Epicardium", "Myocardium", "Endocardium", "Pericardium"]'::jsonb, 1, 'The myocardium is the thick muscular middle layer responsible for the heart''s contractile pumping action.', 'PON 411 · Anatomy & Physiology'),
(1, 62, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Most neurones in the CNS are:', '["Unipolar neurones", "Bipolar neurones", "Pseudounipolar neurones", "Multipolar neurones"]'::jsonb, 3, 'Most CNS neurons, including motor neurons and interneurons, are multipolar: one axon and many dendrites.', 'PON 411 · Anatomy & Physiology'),
(1, 63, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Neurones are also known as:', '["Glial cells", "Ganglia", "Axons", "Nerve cells"]'::jsonb, 3, 'Neurones are nerve cells, the functional units of the nervous system.', 'PON 411 · Anatomy & Physiology'),
(1, 64, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The main function of the medulla oblongata is:', '["Renal control", "Cardiorespiratory control", "Parasympathetic control", "Endocrine control"]'::jsonb, 1, 'The medulla holds the cardiac, vasomotor and respiratory centres.', 'PON 411 · Anatomy & Physiology'),
(1, 65, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Which nerve innervates the diaphragm?', '["Vagus nerve", "Median nerve", "Phrenic nerve", "Radial nerve"]'::jsonb, 2, 'The phrenic nerve (C3–C5) supplies the diaphragm: "C3, 4, 5 keep the diaphragm alive".', 'PON 411 · Anatomy & Physiology'),
(1, 66, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'A patient with blood group O negative is often called the:', '["Rh-positive donor", "Universal recipient", "Universal donor", "Least compatible donor"]'::jsonb, 2, 'O negative red cells lack A, B, and Rh(D) antigens, making them compatible (in emergencies) with recipients of any ABO/Rh type — hence ''universal donor''.', 'PON 411 · Anatomy & Physiology'),
(1, 67, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Filtration of blood in the nephron primarily occurs at the:', '["Loop of Henle", "Collecting duct", "Glomerulus", "Distal convoluted tubule"]'::jsonb, 2, 'The glomerulus, a capillary tuft within Bowman''s capsule, is the site of filtration of plasma into the nephron.', 'PON 411 · Anatomy & Physiology'),
(1, 68, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'The normal cardiac electrical impulse originates in the:', '["AV node", "Sinoatrial (SA) node", "Bundle of His", "Purkinje fibres"]'::jsonb, 1, 'The SA node, located in the right atrium, is the heart''s natural pacemaker and initiates the normal cardiac impulse.', 'PON 411 · Anatomy & Physiology'),
(1, 69, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Gastrointestinal glandular secretions primarily aid in:', '["Filtering blood", "Regulating body temperature exclusively", "Producing red blood cells", "Chemical breakdown of food and enzymatic digestion"]'::jsonb, 3, 'GI glands (salivary, gastric, pancreatic, liver/bile) secrete enzymes and other substances essential for chemically breaking down food.', 'PON 411 · Anatomy & Physiology'),
(1, 70, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'PON 411 · Anatomy & Physiology', 'Cardiac output is calculated as:', '["Stroke volume minus heart rate", "Mean arterial pressure divided by heart rate", "Heart rate divided by stroke volume", "Heart rate multiplied by stroke volume"]'::jsonb, 3, 'Cardiac output (CO) = heart rate (HR) x stroke volume (SV), representing the volume of blood pumped by the heart per minute.', 'PON 411 · Anatomy & Physiology'),
(1, 71, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Normal skin flora such as Staphylococcus epidermidis can cause infection mainly of:', '["The eyes only", "The stomach lining in healthy adults", "Healthy intact skin", "Implants and IV lines"]'::jsonb, 3, 'They form biofilms on plastic and metal.', 'GSM 402 · Microbiology & Infection Control'),
(1, 72, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'When removing (doffing) PPE after caring for an isolated patient, the correct order is:', '["Gloves, goggles, gown, mask, hand hygiene", "Hand hygiene only, with no specific PPE removal order", "Gown first, followed immediately by mask with no hand hygiene between", "Mask first, then gloves, then gown"]'::jsonb, 0, 'PPE doffing removes the most contaminated items first: gloves, then goggles, then gown, then mask, with hand hygiene performed at the end (and often between steps).', 'GSM 402 · Microbiology & Infection Control'),
(1, 73, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'A bacteriostatic antibiotic is one that:', '["Kills only viruses", "Has no effect on bacteria at all", "Kills bacteria directly", "Stops bacteria from multiplying"]'::jsonb, 3, 'Bactericidal drugs kill bacteria.', 'GSM 402 · Microbiology & Infection Control'),
(1, 74, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Surgical site infection risk is reduced by keeping the patient:', '["Very anaemic, with a low haemoglobin", "Hyperglycaemic", "Cold during surgery", "Warm (normothermic) during surgery"]'::jsonb, 3, 'Hypothermia reduces immune function.', 'GSM 402 · Microbiology & Infection Control'),
(1, 75, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'A severely neutropenic chemotherapy patient is admitted. The nurse should implement:', '["Airborne precautions specifically for the patient''s own protection, with no other measures", "Reverse barrier nursing (protective isolation) to protect this patient from external pathogens", "No special precautions are needed", "Standard barrier nursing to protect other patients from this patient"]'::jsonb, 1, 'A severely immunocompromised patient needs reverse barrier nursing (protective isolation) to shield them from external pathogens, the opposite goal of standard source isolation.', 'GSM 402 · Microbiology & Infection Control'),
(1, 76, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'It is an establishment and implementation of policies, procedures, education and monitoring of staff adherence to reduce infection among patients, staff and visitors in ICU or hospital in general', '["Infection prevention", "Infection prevention and control", "Infection prevention and safety", "Infection control"]'::jsonb, 1, 'Establishing policies and monitoring adherence to reduce infection defines infection prevention and control.', 'GSM 402 · Microbiology & Infection Control'),
(1, 77, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Hand hygiene breaks the chain of infection mainly at the:', '["Reservoir", "Susceptible host", "Mode of transmission", "Agent, by killing the organism"]'::jsonb, 2, 'Hands are the main route of spread in hospitals.', 'GSM 402 · Microbiology & Infection Control'),
(1, 78, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Fungal infections in hospital patients are more likely in those who:', '["Are young and healthy, with short day-case surgery and no antibiotics", "Have short day surgery", "Have central lines, broad-spectrum antibiotics or immunosuppression", "Never take antibiotics"]'::jsonb, 2, 'Candida species are the most common.', 'GSM 402 · Microbiology & Infection Control'),
(1, 79, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Surgical asepsis (''sterile technique'') aims to:', '["Eliminate ALL microorganisms and spores", "Only target visible dirt", "Replace the need for hand hygiene", "Reduce germs to a safe level"]'::jsonb, 0, 'Because invasive procedures breach the body''s natural defences, a zero-tolerance approach to microorganisms is required.', 'GSM 402 · Microbiology & Infection Control'),
(1, 80, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Prions, as causes of CJD, are:', '["Fungi that grow in damp areas", "Abnormal infectious proteins", "Viruses", "Bacteria"]'::jsonb, 1, 'They resist normal sterilisation.', 'GSM 402 · Microbiology & Infection Control'),
(1, 81, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Before entering an isolation room for a patient with airborne infection, staff should put on:', '["An N95/FFP3 respirator that has been fit-tested", "No mask, as long as the door is left open", "A cloth mask", "A surgical mask only"]'::jsonb, 0, 'Keep the door closed.', 'GSM 402 · Microbiology & Infection Control'),
(1, 82, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'A ''dirty'' surgical wound carries an infection risk of approximately:', '["10%", "1–5%", "20–30%", "40–50%"]'::jsonb, 3, 'Dirty wounds (with established infection or gross contamination) carry the highest baseline infection risk of the four wound classification categories.', 'GSM 402 · Microbiology & Infection Control'),
(1, 83, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Methicillin-resistant Staphylococcus aureus (MRSA) is usually treated with:', '["Metronidazole alone", "Amoxicillin alone", "Vancomycin or other agents as guided by sensitivity", "Penicillin V taken orally for 5 days"]'::jsonb, 2, 'Prevention relies on hand hygiene and screening.', 'GSM 402 · Microbiology & Infection Control'),
(1, 84, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Klebsiella pneumoniae is a common cause of:', '["Ringworm", "Tetanus", "Malaria and dengue fever", "Hospital-acquired pneumonia and UTI"]'::jsonb, 3, 'Many strains are multidrug-resistant.', 'GSM 402 · Microbiology & Infection Control'),
(1, 85, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Pseudomonas aeruginosa is a particular concern in:', '["Burns and ventilated patients", "Normal gut flora only", "Clean dry wounds", "Healthy intact skin of young adults"]'::jsonb, 0, 'It thrives in moist environments.', 'GSM 402 · Microbiology & Infection Control'),
(1, 86, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Extended-spectrum beta-lactamase (ESBL) organisms are:', '["Viruses that cause colds", "Fungi that live on the skin and cause ringworm and athlete''s foot", "Harmless gut bacteria", "Gram-negative bacteria resistant to many penicillins and cephalosporins"]'::jsonb, 3, 'Carbapenems may be needed; contact precautions apply.', 'GSM 402 · Microbiology & Infection Control'),
(1, 87, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'The preferred route for surgical antibiotic prophylaxis is:', '["Oral", "Topical only", "Intramuscular only", "Systemic (IV)"]'::jsonb, 3, 'IV administration achieves reliable, adequate blood and tissue levels quickly, right when they''re needed.', 'GSM 402 · Microbiology & Infection Control'),
(1, 88, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Lassa fever is spread mainly by:', '["Dog bites and scratches from stray animals", "Mosquito bites", "Contact with urine or droppings of infected rats (Mastomys)", "Eating vegetables"]'::jsonb, 2, 'Health workers need strict barrier precautions.', 'GSM 402 · Microbiology & Infection Control'),
(1, 89, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'The correct order for donning personal protective equipment before entering an isolation room is:', '["Mask, gloves, gown, hand hygiene", "Gloves, mask, gown, hand hygiene", "Hand hygiene, gown, mask, goggles, gloves", "Goggles, gown, hand hygiene, gloves, mask"]'::jsonb, 2, 'Standard donning sequence is hand hygiene first, then gown, mask, goggles/eye protection, and gloves last, ensuring the most contamination-prone items (gloves) go on last.', 'GSM 402 · Microbiology & Infection Control'),
(1, 90, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'An outbreak in a surgical ward is defined as:', '["A full ward of patients with fever", "One case only", "Any patient with a fever", "Two or more linked cases of the same infection"]'::jsonb, 3, 'Report to the infection control team early.', 'GSM 402 · Microbiology & Infection Control'),
(1, 91, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'The target hand hygiene compliance rate in ICU settings is generally considered to be:', '["Compliance targets are not tracked", ">10%", ">90%", ">50%"]'::jsonb, 2, 'Given how critical hand hygiene is to preventing HAIs, a high compliance target (over 90%) is the goal, even though actual ICU compliance is often suboptimal.', 'GSM 402 · Microbiology & Infection Control'),
(1, 92, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Tetanus toxoid vaccine works by:', '["Killing spores in wounds directly", "Stimulating antibodies against the tetanus toxin", "Giving ready-made antibodies", "Preventing all wound infections"]'::jsonb, 1, 'Tetanus immunoglobulin gives immediate passive immunity.', 'GSM 402 · Microbiology & Infection Control'),
(1, 93, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'The ideal environment for most pathogenic bacteria is:', '["Warm, moist and nutrient-rich", "Sterile and dry", "Dry and cold", "Very acidic and dry"]'::jsonb, 0, 'Keep wounds and equipment clean and dry.', 'GSM 402 · Microbiology & Infection Control'),
(1, 94, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'The key difference between sterilisation and disinfection is that sterilisation:', '["Is only used on skin", "Destroys all forms of microbial life, including spores", "Requires no special equipment", "Only reduces the number of vegetative bacteria"]'::jsonb, 1, 'Sterilisation eliminates all microorganisms including bacterial spores, whereas disinfection reduces pathogens but may not eliminate all spores.', 'GSM 402 · Microbiology & Infection Control'),
(1, 95, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Alcohol hand rub is NOT effective against:', '["Influenza virus", "E. coli on the hands", "Staphylococcus aureus", "Clostridioides difficile spores"]'::jsonb, 3, 'Wash with soap and water.', 'GSM 402 · Microbiology & Infection Control'),
(1, 96, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Chlorhexidine has an advantage over povidone-iodine for skin prep because it:', '["Is not flammable when mixed with alcohol", "Works only on wet skin", "Has a longer residual effect on the skin", "Is safe for the eyes and middle ear"]'::jsonb, 2, 'Alcohol-based chlorhexidine is flammable and must dry.', 'GSM 402 · Microbiology & Infection Control'),
(1, 97, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'A high white cell count with many neutrophils most often suggests:', '["Bacterial infection", "Viral infection always", "Anaemia", "Allergy only"]'::jsonb, 0, 'Lymphocytes rise more in viral infections.', 'GSM 402 · Microbiology & Infection Control'),
(1, 98, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'A sharps container should be closed and replaced when it is:', '["About three-quarters full", "Once a month regardless", "Half empty", "Completely overflowing"]'::jsonb, 0, 'Overfilling causes needlestick injuries.', 'GSM 402 · Microbiology & Infection Control'),
(1, 99, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Which of the following is one of the 5 types of transmission-based precautions?', '["Standard precautions", "Contact precautions", "General precautions", "Universal precautions"]'::jsonb, 1, 'Contact precautions (used for organisms like MRSA and C. difficile) is one of the 5 named transmission-based precaution types, alongside droplet, airborne, enhanced barrier, and protective environment.', 'GSM 402 · Microbiology & Infection Control'),
(1, 100, 'Perioperative Mock — Day 5 Morning (Nov 2026)', 'GSM 402 · Microbiology & Infection Control', 'Ebola virus disease is transmitted by:', '["Mosquito bites in rural areas during the rainy season", "Airborne spread over long distances", "Drinking clean water", "Direct contact with blood and body fluids of infected people"]'::jsonb, 3, 'PPE donning and doffing must be supervised.', 'GSM 402 · Microbiology & Infection Control'),
(2, 1, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'A key difference between spinal and epidural anaesthesia is that spinal anaesthesia:', '["Uses a much larger drug volume", "Is always preferred for short procedures under 10 minutes", "Is injected into the subarachnoid space with faster onset", "Cannot cause hypotension"]'::jsonb, 2, 'Spinal anaesthesia delivers a small volume of local anaesthetic directly into the CSF-filled subarachnoid space, producing rapid, dense block, unlike the larger-volume epidural space injection used for epidurals.', 'PAN 414 · Anaesthesia'),
(2, 2, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Which one of the following drugs increase the serum potassium', '["Xylocaine", "Succinylcholine", "Atracurium", "Pancuronium"]'::jsonb, 1, 'Succinylcholine causes a transient rise in serum potassium as part of its depolarising action, a concern in patients at risk of hyperkalaemia.', 'PAN 414 · Anaesthesia'),
(2, 3, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Suxamethonium should be used with caution in eye surgery for a penetrating eye injury because it:', '["Raises intraocular pressure", "Lasts for 24 hours", "Lowers blood pressure to zero", "Causes pupil constriction"]'::jsonb, 0, 'Weigh this against the need for rapid airway control.', 'PAN 414 · Anaesthesia'),
(2, 4, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Laryngospasm at induction or emergence is first treated with:', '["100% oxygen with CPAP via a tight-fitting mask", "Giving oral fluids and asking the patient to swallow", "Removing all monitoring", "Increasing nitrous oxide"]'::jsonb, 0, 'If it persists, deepen anaesthesia or give a small dose of suxamethonium.', 'PAN 414 · Anaesthesia'),
(2, 5, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Which IV induction agent is most suitable for day-case surgery?', '["Propofol", "Diazepam", "Morphine", "Ketamine"]'::jsonb, 0, 'Propofol suits day-case surgery: rapid, clear-headed recovery with little hangover and anti-emetic properties.', 'PAN 414 · Anaesthesia'),
(2, 6, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Hyperbaric (''heavy'') bupivacaine for spinal anaesthesia spreads mainly according to:', '["The patient''s blood group", "Gravity and patient position", "The speed of the IV fluids", "The colour and temperature of the drug in the syringe"]'::jsonb, 1, 'Positioning after injection controls the block height.', 'PAN 414 · Anaesthesia'),
(2, 7, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Before induction, the anaesthetic nurse ensures the following is immediately available:', '["The surgical instruments", "Working suction, airway equipment and emergency drugs", "The discharge letter and the next day''s theatre list", "The patient''s breakfast"]'::jsonb, 1, 'Check the laryngoscope light and spare blades.', 'PAN 414 · Anaesthesia'),
(2, 8, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Regarding depolarizing muscle relaxant metabolism which is correct', '["Hydrolyzed in plasma psedocholine esterase", "Metabolized in the liver", "Metabolized by acetyl choline esterase", "Under go Hoffman elimination"]'::jsonb, 2, 'Depolarising muscle relaxants such as succinylcholine are hydrolysed by plasma (pseudo)cholinesterase, not by acetylcholinesterase (a different enzyme found at the neuromuscular junction).', 'PAN 414 · Anaesthesia'),
(2, 9, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'For anaesthesia in an obese patient, the ''ramped'' position is used to:', '["Reduce the doses of all anaesthetic drugs given to the patient", "Prevent pressure ulcers only", "Improve the view at laryngoscopy and preoxygenation", "Avoid the need for monitoring"]'::jsonb, 2, 'Align the ear with the sternal notch.', 'PAN 414 · Anaesthesia'),
(2, 10, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'The recommended force for cricoid pressure in an awake patient before induction is about:', '["100 N throughout", "10 N, increasing to 30 N after loss of consciousness", "1 N throughout, as more force always causes oesophageal rupture", "No force, just touch"]'::jsonb, 1, 'Too much force can distort the airway.', 'PAN 414 · Anaesthesia'),
(2, 11, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'An epidural test dose (e.g. lidocaine with adrenaline) is given to detect:', '["Correct catheter length inside the epidural space", "The patient''s pain threshold", "Intravascular or intrathecal catheter placement", "Allergy to chlorhexidine"]'::jsonb, 2, 'Tachycardia suggests intravascular; rapid dense block suggests intrathecal.', 'PAN 414 · Anaesthesia'),
(2, 12, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Depolarizing block may be done by:', '["rocuronuim", "Succinylcholine", "Atracurium", "Neostegmin"]'::jsonb, 1, 'Succinylcholine produces its neuromuscular block by persistent depolarisation of the motor endplate.', 'PAN 414 · Anaesthesia'),
(2, 13, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'A common intubating dose of rocuronium for rapid sequence induction is:', '["5 mg total", "10 mg/kg, to give paralysis lasting the whole case", "0.01 mg/kg", "1.0–1.2 mg/kg"]'::jsonb, 3, 'At this dose, intubating conditions are reached in about 60 seconds.', 'PAN 414 · Anaesthesia'),
(2, 14, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Sevoflurane is preferred for inhalational (gas) induction because it is:', '["Very pungent and causes coughing", "Explosive in oxygen, so it is safer to give by mask", "Given only intravenously", "Non-pungent and does not irritate the airway"]'::jsonb, 3, 'Desflurane is pungent and unsuitable for gas induction.', 'PAN 414 · Anaesthesia'),
(2, 15, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Regional anaesthesia is contraindicated in', '["Diagnosis of placenta previa", "Thrombocytopenia and elevated bleeding time", "Abrutio placenta", "Eclampsia"]'::jsonb, 3, 'Eclampsia with coagulopathy or haemodynamic instability is a contraindication to neuraxial techniques; regional anaesthesia is otherwise often preferred in obstetrics.', 'PAN 414 · Anaesthesia'),
(2, 16, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'A patient with severe systemic disease that is a constant threat to life is ASA:', '["VI", "IV", "II", "I"]'::jsonb, 1, 'ASA V is moribund; ASA VI is brain-dead organ donor; ''E'' marks emergency.', 'PAN 414 · Anaesthesia'),
(2, 17, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'A bispectral index (BIS) value of 40–60 during general anaesthesia indicates:', '["Too deep anaesthesia needing reversal", "The patient is fully awake", "Brain death", "An adequate depth of anaesthesia"]'::jsonb, 3, 'It may help reduce awareness in TIVA.', 'PAN 414 · Anaesthesia'),
(2, 18, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Intravenous regional anesthesia is more commonly used for operations of:', '["Upper limbs", "Lower limbs", "Lower abdomen", "Neck surgeries"]'::jsonb, 0, 'Intravenous regional anaesthesia (Bier''s block) is most commonly used for short procedures on the upper limb using a double tourniquet technique.', 'PAN 414 · Anaesthesia'),
(2, 19, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Which is correct regarding colour coding of anaesthetic gas cylinders?', '["Nitrous oxide – blue", "Cyclopropane – red", "Helium – orange", "Oxygen – black with grey shoulders"]'::jsonb, 0, 'Cylinder colours (ISO): oxygen white (UK: black body with white shoulders), nitrous oxide blue, CO2 grey, cyclopropane orange, helium brown.', 'PAN 414 · Anaesthesia'),
(2, 20, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'One of the fastest-acting inhalational agents is:', '["Sevoflurane", "Ether", "Isoflurane", "Halothane"]'::jsonb, 0, 'Sevoflurane has low blood–gas solubility, so induction and recovery are fast; it is also pleasant to breathe, making it good for inhalational induction.', 'PAN 414 · Anaesthesia'),
(2, 21, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'The nerve most commonly stimulated to monitor neuromuscular blockade is the:', '["Radial", "Ulnar", "Facial", "Median"]'::jsonb, 1, 'Train-of-four monitoring usually stimulates the ulnar nerve and watches the adductor pollicis (thumb).', 'PAN 414 · Anaesthesia'),
(2, 22, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Glycopyrrolate is given with neostigmine to:', '["Increase the muscle relaxation", "Cause sedation and amnesia during the reversal phase", "Prevent bradycardia and secretions from muscarinic effects", "Reverse opioid effects"]'::jsonb, 2, 'Neostigmine increases acetylcholine at all cholinergic receptors.', 'PAN 414 · Anaesthesia'),
(2, 23, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Which factor REDUCES the MAC of volatile agents?', '["Chronic alcohol abuse", "Hyperthermia", "Young childhood", "Old age and pregnancy"]'::jsonb, 3, 'Opioids, hypothermia and sedatives also lower MAC.', 'PAN 414 · Anaesthesia'),
(2, 24, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Ultrasound guidance for peripheral nerve blocks mainly improves:', '["Muscle relaxation for intubation", "The speed of general anaesthesia", "The patient''s fasting status and the timing of the operation list", "Accuracy and safety, with less local anaesthetic needed"]'::jsonb, 3, 'Nerves, vessels and the spreading drug can be seen.', 'PAN 414 · Anaesthesia'),
(2, 25, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Adequate recovery from neuromuscular blockade before extubation is shown by a train-of-four ratio of at least:', '["0.9", "0.1", "0.3 (30% of baseline)", "0.5"]'::jsonb, 0, 'A lower ratio means residual paralysis and aspiration risk.', 'PAN 414 · Anaesthesia'),
(2, 26, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Minimum fasting time for a light meal before elective anaesthesia is generally:', '["2 hours", "24 hours", "6 hours", "1 hour"]'::jsonb, 2, 'A light meal requires at least 6 hours of fasting to allow adequate gastric emptying and reduce aspiration risk during induction.', 'PAN 414 · Anaesthesia'),
(2, 27, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Standard preoperative fasting guidance for clear fluids before elective surgery is:', '["12 hours", "6 hours", "2 hours", "No restriction needed"]'::jsonb, 2, 'Clear fluids may be taken up to 2 hours before elective surgery under modern fasting guidelines, reducing unnecessary dehydration without increasing aspiration risk.', 'PAN 414 · Anaesthesia'),
(2, 28, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Before anaesthesia, beta-blockers taken long term should usually be:', '["Stopped one week before", "Continued, including on the morning of surgery", "Replaced with aspirin", "Doubled on the day of surgery to prevent tachycardia"]'::jsonb, 1, 'Stopping suddenly can cause rebound tachycardia and ischaemia.', 'PAN 414 · Anaesthesia'),
(2, 29, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'The most common causes of anaphylaxis during anaesthesia are:', '["Sterile water and lubricants", "Normal saline and dextrose", "Oxygen and nitrous oxide from the anaesthetic machine", "Neuromuscular blockers, antibiotics and chlorhexidine"]'::jsonb, 3, 'Treat with adrenaline, fluids, oxygen and stop the trigger.', 'PAN 414 · Anaesthesia'),
(2, 30, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'The two-bag test on an anaesthetic machine checks:', '["The patient''s blood group", "The steriliser pressure", "The oxygen cylinder colour code and the pin-index system", "The breathing system''s valves and integrity with a test lung"]'::jsonb, 3, 'It is part of the routine machine check.', 'PAN 414 · Anaesthesia'),
(2, 31, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Accidental intra-arterial injection of thiopentone can cause:', '["Increased wound healing", "Harmless warmth only, which settles after a few minutes", "Instant cure of hypertension", "Severe pain, arterial spasm and gangrene of the limb"]'::jsonb, 3, 'Leave the cannula in place and treat urgently.', 'PAN 414 · Anaesthesia'),
(2, 32, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'The dose of suxthamethonium for intubation is', '["0.2mg/kg", "100mg for adult", "1gm for pediatrics", "2mg/kg"]'::jsonb, 3, 'Succinylcholine''s typical intubating dose is commonly cited as up to 1-2mg/kg IV for rapid, reliable paralysis during induction.', 'PAN 414 · Anaesthesia'),
(2, 33, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'The volatile agent with the highest MAC (lowest potency) of these is:', '["Isoflurane (about 1.15%)", "Desflurane (about 6%)", "Halothane (about 0.75%)", "Sevoflurane (about 2%)"]'::jsonb, 1, 'Higher MAC means lower potency.', 'PAN 414 · Anaesthesia'),
(2, 34, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'Which neuromuscular blocker has the fastest onset of action?', '["Atracurium", "Succinylcholine", "Mivacurium", "Vecuronium"]'::jsonb, 1, 'Succinylcholine (suxamethonium) acts in 30–60 seconds, the fastest onset, which is why it is used for rapid-sequence induction.', 'PAN 414 · Anaesthesia'),
(2, 35, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 414 · Anaesthesia', 'In which one of the following situations atropine is best indicated?', '["Bradycardia", "Hypotension", "Hypertension", "Tachycardia"]'::jsonb, 0, 'Atropine, an anticholinergic, blocks vagal effects on the heart and is the first-line drug for symptomatic bradycardia.', 'PAN 414 · Anaesthesia'),
(2, 36, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Cefazolin for surgical prophylaxis should be repeated during surgery if:', '["The operation lasts longer than about 4 hours or blood loss is large", "The patient asks for it", "The operation is a short day case", "The surgeon changes gloves"]'::jsonb, 0, 'Redosing keeps tissue levels effective.', 'PAN 412 · Pharmacology'),
(2, 37, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Poisoning management in the ICU may include gastric lavage, which is most effective when performed:', '["Within about 1 hour of ingestion (up to 2–4 hours in some cases), and never in corrosive poisoning", "Only in infants", "More than 24 hours after ingestion", "At any time regardless of the substance ingested"]'::jsonb, 2, 'Gastric lavage is most useful shortly after ingestion (roughly within 1–4 hours) and is contraindicated in corrosive/caustic poisoning due to perforation risk.', 'PAN 412 · Pharmacology'),
(2, 38, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'When titrating sedation in a mechanically ventilated ICU patient, the nurse should primarily use:', '["Blood pressure alone as the only guide", "No formal scale — sedation should be maximised at all times", "A validated sedation scale (e.g. RASS) to guide titration", "The patient''s family''s preference alone"]'::jsonb, 2, 'Validated sedation scales such as the Richmond Agitation-Sedation Scale (RASS) guide safe titration, avoiding both under- and over-sedation.', 'PAN 412 · Pharmacology'),
(2, 39, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Bronchodilator nebulisers (e.g. salbutamol) can cause which common side effect that the nurse should monitor for?', '["Bradycardia and sedation", "Weight gain", "Tachycardia and tremor", "Hypoglycaemia"]'::jsonb, 2, 'Beta-2 agonist bronchodilators commonly cause tachycardia and fine tremor as expected sympathomimetic side effects.', 'PAN 412 · Pharmacology'),
(2, 40, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Which action should the nurse take when preparing patient-controlled analgesia for a postoperative patient?', '["Ask another nurse to double-check the setup before patient use.", "Provide clear, simple instructions for dosing if the patient is cognitively impaired", "Instruct the patient to administer a dose only when experiencing pain.", "Caution the patient to limit the number of times he presses the dosing button."]'::jsonb, 0, 'Having a second nurse double-check PCA setup is a core safety practice before patient use.', 'PAN 412 · Pharmacology'),
(2, 41, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Which of these drugs is used as an antidote for narcotics', '["Atropine", "Black charcoal", "Nalaxone", "Cimetidine"]'::jsonb, 2, 'Naloxone is the antidote for narcotic (opioid) overdose.', 'PAN 412 · Pharmacology'),
(2, 42, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A thyroidectomy patient complains of palpitations and anxiety preoperatively. The nurse should administer:', '["Morphine", "Propanolol", "Adrenaline", "Dopamine"]'::jsonb, 1, 'Propranolol controls the adrenaline-driven symptoms (palpitations, anxiety, tremor) of residual hyperthyroidism.', 'PAN 412 · Pharmacology'),
(2, 43, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Which drug is NOT used to treat hypotension in ICU?', '["Dopamine", "Hydralazine", "Dobutamine", "Noradrenaline"]'::jsonb, 1, 'Dopamine, noradrenaline and dobutamine raise BP or cardiac output. Hydralazine is a vasodilator that lowers BP.', 'PAN 412 · Pharmacology'),
(2, 44, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A patient on a propofol infusion develops metabolic acidosis and rhabdomyolysis. The nurse suspects:', '["Anaphylaxis", "Propofol infusion syndrome", "Malignant hyperthermia", "Serotonin syndrome"]'::jsonb, 1, 'PRIS is a rare but fatal complication of propofol, characterized by lactic acidosis, rhabdomyolysis, and cardiac failure.', 'PAN 412 · Pharmacology'),
(2, 45, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A patient on IV nitroglycerin has a headache. Which action is BEST?', '["Switch to oral nitrates", "Administer PRN acetaminophen", "Hold the next dose", "Increase the infusion rate"]'::jsonb, 1, 'Headache is a common side effect of nitrates. Acetaminophen is appropriate; tolerance develops over time.', 'PAN 412 · Pharmacology'),
(2, 46, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'NPH insulin is given at 07:30. When will it reach its peak effect?', '["11:30–13:30", "13:30–19:30", "17:30–23:30", "15:30–21:30"]'::jsonb, 1, 'NPH (intermediate) insulin peaks about 6–12 hours after injection, so a 07:30 dose peaks around 13:30–19:30.', 'PAN 412 · Pharmacology'),
(2, 47, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A recognised adverse effect of inotropic infusions (e.g. dobutamine) is:', '["Tachyarrhythmias and myocardial ischaemia", "Hypoglycaemia", "Bradycardia", "Reduced myocardial oxygen demand"]'::jsonb, 0, 'Inotropes such as dobutamine, dopamine and adrenaline raise contractility but can cause tachycardia, arrhythmias and myocardial ischaemia by increasing oxygen demand.', 'PAN 412 · Pharmacology'),
(2, 48, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A commonly prescribed mast cell stabilizer used for asthma is:', '["Cromolyn sodium", "Theophylline", "Albuterol", "Budesonide"]'::jsonb, 0, 'Cromolyn sodium is a classic mast cell stabiliser used in asthma prevention.', 'PAN 412 · Pharmacology'),
(2, 49, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Which antibiotic acts as a protein synthesis inhibitor?', '["Trimethoprim", "Cefotaxime", "Penicillin", "Tetracycline"]'::jsonb, 3, 'Tetracyclines bind the 30S ribosomal subunit and block protein synthesis. Penicillins and cephalosporins act on the cell wall; trimethoprim blocks folate.', 'PAN 412 · Pharmacology'),
(2, 50, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'The antidote used to reverse benzodiazepine sedation is:', '["Acetylcysteine", "Flumazenil", "Protamine sulphate", "Naloxone"]'::jsonb, 1, 'Flumazenil blocks the same receptor benzodiazepines act on, though caution is needed in dependent patients.', 'PAN 412 · Pharmacology'),
(2, 51, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Ondansetron is a:', '["5-HT₃ receptor antagonist", "Dopamine agonist", "Opioid agonist", "Beta-blocker"]'::jsonb, 0, 'It can prolong the QT interval.', 'PAN 412 · Pharmacology'),
(2, 52, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A patient receiving IV heparin has an aPTT of 110 seconds. Which reversal agent should be available?', '["Andexanet alfa", "Vitamin K", "Idarucizumab", "Protamine sulfate"]'::jsonb, 3, 'Protamine sulfate reverses heparin. Vitamin K is for warfarin; idarucizumab/andexanet for DOACs.', 'PAN 412 · Pharmacology'),
(2, 53, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'The specific reversal agent for unfractionated heparin is:', '["Protamine sulfate", "Vitamin K", "Fresh frozen plasma only", "Dantrolene"]'::jsonb, 0, 'Protamine sulfate binds and neutralises heparin, providing rapid reversal of its anticoagulant effect.', 'PAN 412 · Pharmacology'),
(2, 54, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Which one of the following drug is administered every 3-5 minutes of CPR?', '["Amiodarone", "Epinephrine", "Vasopressin", "Atropine"]'::jsonb, 1, 'Epinephrine is re-dosed every 3-5 minutes during resuscitation.', 'PAN 412 · Pharmacology'),
(2, 55, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Hypnotic drugs, as a pharmacological class, are primarily used to:', '["Treat hypertension", "Induce and maintain sleep", "Reverse anticoagulation", "Increase heart rate"]'::jsonb, 1, 'Hypnotics are a class of drugs used specifically to induce and/or maintain sleep.', 'PAN 412 · Pharmacology'),
(2, 56, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Which of the following drugs inhibits thyroid hormone synthesis preoperatively?', '["Adrenaline", "Propanolol", "Dopamine", "Carbimazole"]'::jsonb, 3, 'Carbimazole blocks thyroid peroxidase, reducing new hormone synthesis before surgery.', 'PAN 412 · Pharmacology'),
(2, 57, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Hypnotic medications differ from anxiolytics primarily in their main clinical purpose, which is to:', '["Lower blood pressure", "Induce and maintain sleep", "Treat bacterial infections", "Reduce anxiety during waking hours specifically"]'::jsonb, 1, 'While some drug classes overlap, hypnotics are specifically used to induce/maintain sleep, distinct from anxiolytics'' primary anti-anxiety purpose.', 'PAN 412 · Pharmacology'),
(2, 58, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Tranexamic acid reduces surgical bleeding by:', '["Constricting all arteries", "Activating platelets directly", "Inhibiting fibrinolysis (clot breakdown)", "Replacing clotting factors"]'::jsonb, 2, 'It is given in major trauma, orthopaedics and PPH.', 'PAN 412 · Pharmacology'),
(2, 59, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A patient with myasthenia gravis is prescribed neostigmine. The nurse should monitor for:', '["Serotonin syndrome", "Neuroleptic malignant syndrome", "Cholinergic crisis", "Thyroid storm"]'::jsonb, 2, 'Overdose of acetylcholinesterase inhibitors (e.g., neostigmine) causes cholinergic crisis (SLUDGE syndrome).', 'PAN 412 · Pharmacology'),
(2, 60, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Which of these is Not Opioid Analgesic Drug', '["Fentanyl,", "Morphine", "Pethidine", "Ketorolac"]'::jsonb, 3, 'Ketorolac is an NSAID, not an opioid, unlike morphine, pethidine, and fentanyl.', 'PAN 412 · Pharmacology'),
(2, 61, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Excessive anticoagulation with bleeding due to warfarin can be reversed by:', '["Vitamin K", "Diuretics", "Protamine sulphate", "Aspirin"]'::jsonb, 0, 'Warfarin is reversed with vitamin K (phytomenadione), plus prothrombin complex concentrate or FFP for major bleeding.', 'PAN 412 · Pharmacology'),
(2, 62, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Streptomycin is produced by which organism?', '["Streptomyces fradiae", "Streptomyces noursei", "Streptomyces nodosus", "Streptomyces griseus"]'::jsonb, 3, 'Streptomycin was isolated from Streptomyces griseus (Waksman, 1943).', 'PAN 412 · Pharmacology'),
(2, 63, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'When preparing patient-controlled analgesia (PCA) for a postoperative patient, the nurse should:', '["Give dosing instructions to a cognitively impaired patient", "Tell the patient to dose only when in severe pain", "Ask another nurse to double-check the setup before use", "Tell the patient to limit button presses"]'::jsonb, 2, 'PCA pumps are high-alert. An independent double-check of the drug, concentration and settings prevents fatal programming errors.', 'PAN 412 · Pharmacology'),
(2, 64, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'A patient on fentanyl PCA has a respiratory rate of 8/min and is somnolent. Which antidote should the nurse administer?', '["Romazicon", "Flumazenil", "Naloxone", "Physostigmine"]'::jsonb, 2, 'Naloxone reverses opioid-induced respiratory depression. Flumazenil reverses benzodiazepines.', 'PAN 412 · Pharmacology'),
(2, 65, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PAN 412 · Pharmacology', 'Metformin is usually withheld before surgery with iodinated contrast or major surgery because of the risk of:', '["Hypertension", "Hyperkalaemia", "Hypoglycaemia", "Lactic acidosis"]'::jsonb, 3, 'Restart when kidney function and eating are normal.', 'PAN 412 · Pharmacology'),
(2, 66, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Postoperative hypertension in PACU with a full bladder is best treated by:', '["Sedating the patient deeply at once to lower the blood pressure", "Emptying the bladder (voiding or catheter)", "Restricting oxygen to slow the heart", "Giving IV hydralazine as the first step"]'::jsonb, 1, 'Treat pain, anxiety and bladder distension before drugs.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 67, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient in PACU who received a large volume of irrigation fluid during TURP becomes confused with low sodium. This suggests:', '["Normal emergence from anaesthesia", "Hypercalcaemia from immobility after the operation", "Allergy to the urinary catheter", "TURP syndrome from fluid absorption"]'::jsonb, 3, 'Restrict fluids, check sodium and inform the team.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 68, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'In PACU, a patient''s blood pressure is 220/120 mmHg. Before giving drugs, the nurse should check:', '["The surgeon''s name and grade, and the theatre the patient came from", "Pain, full bladder, hypoxia and a correct reading", "The time of the next theatre case", "The patient''s usual diet at home"]'::jsonb, 1, 'Use a correctly sized cuff.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 69, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A post-operative patient with high-flow suction on a nasogastric tube in PACU should be monitored for:', '["Polycythaemia caused by the suction pump", "Hyperglycaemia only, from the stress response", "Rapid weight gain from fluid retention in the abdominal wall", "Fluid and electrolyte losses, mainly potassium"]'::jsonb, 3, 'Record NG output on the fluid chart.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 70, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Nerve damage can occur as a complication of surgery. Which assessment finding should the nurse prioritize in a patient with suspected nerve damage?', '["Elevated temperature", "Increased heart rate", "Sensory changes", "Abdominal pain"]'::jsonb, 2, 'Sensory changes (numbness, altered sensation) are a key assessment finding suggesting postoperative nerve injury.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 71, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Which physiological response is commonly associated with surgical stress?', '["Bronchial constriction", "Decreased cortisol levels", "Sodium and water retention", "Peripheral vasodilation"]'::jsonb, 2, 'The surgical stress response releases ADH, aldosterone and cortisol, so the body retains sodium and water.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 72, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'After a long case in lithotomy, the PACU nurse checks the legs for:', '["Hair growth and changes in skin colour", "Tattoos and old scars on the legs from previous operations", "Nerve injury, pressure damage and compartment syndrome", "Nail colour and nail bed shape only"]'::jsonb, 2, 'Prolonged lithotomy can cause well-leg compartment syndrome.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 73, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Hypotension in PACU in a patient with a working thoracic epidural is most often due to:', '["Sympathetic block causing vasodilation", "Hyperthermia from forced-air warming during surgery", "Overhydration during surgery", "Hypertension caused by pain"]'::jsonb, 0, 'Treat with fluids, vasopressor and reduce the infusion; exclude bleeding.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 74, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'In PACU, ''early warning score'' charts help nurses to:', '["Recognise deterioration early and escalate", "Order surgical instruments for theatre", "Calculate drug doses for each patient", "Book theatre lists and order instruments for the next day"]'::jsonb, 0, 'Scores combine vital signs into a single number.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 75, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient in PACU develops pink frothy sputum and hypoxia after an episode of laryngospasm. This is likely:', '["Negative pressure pulmonary oedema", "An acute asthma attack from the volatile agent", "Aspiration of blood from the nose", "Normal recovery"]'::jsonb, 0, 'Forceful breathing against a closed glottis pulls fluid into the alveoli.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 76, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Pain in a sedated patient who cannot speak can be assessed using:', '["The patient''s appetite and fluid intake", "The blood glucose level", "The colour of the urine", "A behavioural pain scale"]'::jsonb, 3, 'Examples are FLACC (children) and CPOT.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 77, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'The most common preventable complication of abdominal surgery is:', '["Urinary retention", "Thrombophlebitis", "Atelectasis", "Fluid and electrolyte imbalance"]'::jsonb, 2, 'Atelectasis is the commonest preventable complication after abdominal surgery (pain-limited breathing). Prevent it with deep breathing, incentive spirometry and early mobilisation.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 78, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Monitor alarms in PACU should be:', '["Turned off to reduce noise in the busy unit", "Set to the widest possible limits for all patients to reduce noise", "Silenced permanently during the night shift", "Set to suitable limits and checked before silencing"]'::jsonb, 3, 'Alarm fatigue causes missed deterioration.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 79, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient in PACU has a fever of 38.2 °C two hours after surgery. The most likely cause is:', '["The normal inflammatory response to surgery", "Pneumonia from aspiration during the induction", "A wound infection that is already established", "A urinary tract infection from the catheter"]'::jsonb, 0, 'A very high temperature with rigidity suggests malignant hyperthermia.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 80, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Children in PACU are at higher risk than adults of:', '["Myocardial infarction and angina", "Gallstones and biliary colic after fasting", "Laryngospasm and rapid desaturation", "Prostate problems and retention"]'::jsonb, 2, 'They have smaller airways and higher oxygen use.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 81, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'The modified Aldrete score assesses activity, respiration, circulation, consciousness and:', '["Oxygen saturation", "Pain score on a 0–10 scale", "Urine output", "Blood glucose"]'::jsonb, 0, 'A score of 9 or more out of 10 usually allows discharge to the ward.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 82, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient in PACU after major abdominal surgery has a rising heart rate, falling BP and cool peripheries. The first step is:', '["Reduce the IV fluids to protect the heart from overload, and observe", "Discharge the patient to the ward for routine observations", "Give a sedative and wait to see if the vital signs settle", "Look for bleeding, give oxygen and IV fluid, call the surgeon"]'::jsonb, 3, 'Hypovolaemia from bleeding is the commonest cause.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 83, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Which patient in PACU is at highest risk of aspiration?', '["One who is drowsy, vomiting and lying flat", "One with normal swallowing and a cough", "One without nausea who is lying on the side", "One sitting up and fully awake and alert"]'::jsonb, 0, 'Turn to the side and suction.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 84, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A post-operative patient who received a non-depolarising blocker is weak and anxious. Before giving more reversal, the anaesthetist may check:', '["Hourly urine output", "Pupil size and reaction", "Blood alcohol level and liver function tests", "Train-of-four with a nerve stimulator"]'::jsonb, 3, 'This guides whether further reversal is needed.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 85, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'The ''tonsillar position'' for recovery after tonsillectomy is:', '["Sitting fully upright in bed", "Supine and flat on the back with the head turned up", "Semi-prone (lateral), head slightly down", "Prone with the face downwards"]'::jsonb, 2, 'Blood and secretions drain out of the mouth.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 86, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Following surgery, a patient develops signs of seroma formation. Which intervention is appropriate for managing this complication?', '["Manual compression to the affected site", "Applying heat packs to the area", "Encouraging increased fluid intake", "Drainage of the fluid through a needle"]'::jsonb, 3, 'Needle drainage removes the accumulated fluid and relieves a symptomatic seroma.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 87, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'The Apfel score for PONV includes female sex, non-smoker, history of PONV or motion sickness and:', '["Use of local anaesthetic", "Age over 80", "Postoperative opioid use", "Blood group O"]'::jsonb, 2, 'Each factor raises the risk by about 20%.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 88, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Multimodal analgesia after surgery means:', '["Withholding analgesia until pain is severe", "Giving one single large dose of opioid", "Using only one drug, repeated hourly until the pain goes", "Combining drugs that act at different sites"]'::jsonb, 3, 'It improves pain relief with fewer side effects.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 89, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'To prevent atelectasis postoperatively, the nurse encourages:', '["Incentive spirometry", "Supine position", "Fluid restriction", "Bed rest"]'::jsonb, 0, 'Incentive spirometry promotes lung expansion.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 90, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A common first-line antiemetic dose of ondansetron in adults in PACU is:', '["4 mg IV", "0.4 mg IV", "400 mg orally", "40 mg IV"]'::jsonb, 0, 'Use another drug class if the first one fails.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 91, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient s/p thyroidectomy has stridor and agitation. The nurse should:', '["Administer morphine", "Prepare for reintubation", "Encourage coughing", "Apply oxygen"]'::jsonb, 1, 'Stridor suggests laryngeal edema or hematoma, risking airway obstruction.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 92, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'The PADSS (Post-Anaesthesia Discharge Scoring System) is used mainly for:', '["Assessing need for ICU admission", "Discharging day-case patients home", "Scoring pain only, at rest and on movement", "Predicting the risk of PONV"]'::jsonb, 1, 'It scores vital signs, activity, nausea, pain and bleeding.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 93, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient with PCA morphine has a respiratory rate of 8/min. The nurse should:', '["Administer naloxone", "Discontinue PCA", "Increase oxygen flow", "Stimulate the patient"]'::jsonb, 0, 'Naloxone reverses opioid-induced respiratory depression.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 94, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Which of the following postoperative complications involves the abnormal accumulation of fluid at the surgical site?', '["Urinary retention", "Paralytic ileus", "Seroma", "Adhesion formation"]'::jsonb, 2, 'A seroma is a localised collection of serous fluid at the surgical site.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 95, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient s/p hip replacement has acute confusion. The nurse FIRST assesses for:', '["Urinary retention", "Hypoxia", "Stroke", "Pain"]'::jsonb, 1, 'Hypoxia is a reversible cause of delirium.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 96, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'The nurse assesses epidural block height in PACU by testing sensation to:', '["A bright light shone into the eyes", "Cold, such as ice or ethyl chloride spray", "A loud noise close to each ear and on both sides of the neck", "Light touch on the face and neck"]'::jsonb, 1, 'Record the level and compare both sides.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 97, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Postoperative delirium in elderly patients is reduced by:', '["High doses of benzodiazepines given regularly at night", "Physical restraints on the bed to stop the patient falling", "Keeping them in a dark, noisy room for most of the day and night", "Good pain control, glasses and hearing aids, and fewer sedatives"]'::jsonb, 3, 'Delirium increases length of stay and mortality.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 98, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Before discharge from PACU, wound drains and dressings should be:', '["Covered with extra tape and not checked", "Ignored if the patient is awake and alert", "Checked, with the drainage volume recorded", "Removed in all patients before leaving, so the ward has less work"]'::jsonb, 2, 'Sudden high drain output should be reported.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 99, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'A patient who had spinal anaesthesia complains of a headache in PACU. The nurse should first:', '["Sit the patient up straight and ignore the complaint", "Discharge the patient to the ward without review", "Assess the headache and vital signs, and tell the anaesthetist", "Give a large dose of IV morphine straight away and lie the patient flat"]'::jsonb, 2, 'True post-dural puncture headache usually appears later and is postural.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(2, 100, 'Perioperative Mock — Day 5 Afternoon (Nov 2026)', 'PON 415 · Post-Anaesthesia Care (PACU)', 'Which postoperative complication is most likely to occur in a patient with a history of deep vein thrombosis (DVT)?', '["Pulmonary embolism", "Organ injury", "Urinary retention", "Paralytic ileus"]'::jsonb, 0, 'A history of DVT increases the risk that a dislodged clot will travel to the pulmonary circulation, causing a pulmonary embolism.', 'PON 415 · Post-Anaesthesia Care (PACU)'),
(3, 1, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'The most important post-operative observation after a thyroidectomy in the first hours is:', '["Airway and breathing, watching for neck swelling", "Hearing and balance after surgery", "Leg pulses and capillary refill in both feet", "Bowel sounds and passing of flatus"]'::jsonb, 0, 'Bleeding can compress the airway.', 'PON 416 · General Surgery'),
(3, 2, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'The nurse places the thyroidectomy patient in semi-Fowler''s position to:', '["Increase venous pressure", "Reduce edema and venous congestion", "Enhance secretion drainage", "Promote calcium absorption"]'::jsonb, 1, 'Semi-Fowler''s position reduces venous congestion and swelling at the operative site.', 'PON 416 · General Surgery'),
(3, 3, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'A transverse loop colostomy is usually:', '["Made from the small bowel (ileum)", "Placed low in the groin crease, below the belt line", "Temporary, to protect a distal join", "Always permanent after any surgery"]'::jsonb, 2, 'It is later closed.', 'PON 416 · General Surgery'),
(3, 4, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'A perianal abscess is treated by:', '["Hot packs only", "Banding", "Antibiotics alone in all cases", "Incision and drainage"]'::jsonb, 3, 'Antibiotics alone usually fail.', 'PON 416 · General Surgery'),
(3, 5, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'An amoebic liver abscess is usually treated first with:', '["Surgery in all cases", "Steroids", "Metronidazole", "Chemotherapy"]'::jsonb, 2, 'Aspiration is reserved for large or non-responding abscesses.', 'PON 416 · General Surgery'),
(3, 6, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'A patient with acute appendicitis suddenly gets relief from pain, then develops fever and diffuse tenderness. This suggests:', '["Constipation", "Gastritis caused by the painkillers given", "Perforation with peritonitis", "Resolution of appendicitis"]'::jsonb, 2, 'Pain relief may come briefly after the appendix bursts.', 'PON 416 · General Surgery'),
(3, 7, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'Before an emergency laparotomy, the patient is kept nil by mouth mainly to:', '["Lower the blood pressure", "Prevent dehydration before surgery", "Improve wound healing later", "Reduce the risk of aspiration"]'::jsonb, 3, 'An NG tube may also be passed to empty the stomach.', 'PON 416 · General Surgery'),
(3, 8, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'Dumping syndrome after gastrectomy causes:', '["Jaundice and itching after fatty meals", "Haematuria and loin pain soon after eating a meal", "Weight gain and constipation after meals", "Sweating, palpitations and diarrhoea after meals"]'::jsonb, 3, 'Advise small, frequent, low-sugar meals and avoid drinking with meals.', 'PON 416 · General Surgery'),
(3, 9, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'The Alvarado score is used to:', '["Estimate the chance of appendicitis", "Classify groin hernias as direct or indirect", "Assess pancreatitis severity", "Grade the depth of a burn"]'::jsonb, 0, 'It combines symptoms, signs and white cell count.', 'PON 416 · General Surgery'),
(3, 10, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'Post-operative hiccups that persist after upper abdominal surgery may indicate:', '["Urinary retention after the catheter is removed", "Ankle swelling from the IV fluids given", "Normal healing of the abdominal wound", "Irritation of the diaphragm, e.g. a collection"]'::jsonb, 3, 'Look for fever and imaging evidence.', 'PON 416 · General Surgery'),
(3, 11, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'Pyloromyotomy, gastrojejunostomy and vagotomy are all operations on the:', '["Gallbladder", "Large bowel", "Stomach and pylorus", "Spleen and splenic vessels"]'::jsonb, 2, 'Gastric surgery may cause dumping and vitamin B12 deficiency.', 'PON 416 · General Surgery'),
(3, 12, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'A femoral hernia is more common in:', '["Newborn boys", "Women", "Young men only", "Children"]'::jsonb, 1, 'It lies below and lateral to the pubic tubercle.', 'PON 416 · General Surgery'),
(3, 13, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'Laparoscopic surgery compared with open surgery usually gives:', '["More pain and a longer hospital stay", "Less pain, smaller scars and faster recovery", "No need for any general anaesthesia or skin incision", "Larger scars but less risk of infection"]'::jsonb, 1, 'Conversion to open surgery may be needed.', 'PON 416 · General Surgery'),
(3, 14, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'A Whipple''s procedure (pancreaticoduodenectomy) is done for:', '["Gallstones only, without cancer", "An inguinal hernia in men over 60 years old", "Acute appendicitis in adults", "Cancer of the head of the pancreas"]'::jsonb, 3, 'It is a major operation with several anastomoses.', 'PON 416 · General Surgery'),
(3, 15, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'The tumour marker often used to follow up colorectal cancer is:', '["CEA", "AFP", "PSA", "CA-125"]'::jsonb, 0, 'Rising CEA after surgery may indicate recurrence.', 'PON 416 · General Surgery'),
(3, 16, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'After splenectomy, the patient needs vaccines against pneumococcus, meningococcus and:', '["Haemophilus influenzae type b", "Yellow fever only, before travelling abroad", "Cholera and typhoid", "Rabies and dog-bite tetanus"]'::jsonb, 0, 'Lifelong risk of overwhelming post-splenectomy infection.', 'PON 416 · General Surgery'),
(3, 17, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'The Lichtenstein repair of an inguinal hernia uses:', '["Only simple sutures pulled under tension to close the defect", "A tension-free mesh over the posterior wall", "Removal of the spermatic cord and testis", "Closure of the deep ring with steel wire"]'::jsonb, 1, 'Mesh repairs have lower recurrence rates.', 'PON 416 · General Surgery'),
(3, 18, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'A pancreatic pseudocyst is:', '["A large gallstone in the pancreatic duct", "A pancreatic fluid collection walled off by fibrous tissue", "A slow-growing cancer of the pancreas with a fluid-filled centre", "An inflamed appendix lying near the pancreas"]'::jsonb, 1, 'It usually forms 4 weeks or more after acute pancreatitis.', 'PON 416 · General Surgery'),
(3, 19, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'A breast abscess in a breastfeeding mother is managed by:', '["Drainage, antibiotics and continued breastfeeding or expressing", "Radiotherapy to the breast and stopping breastfeeding on both sides", "Stopping breastfeeding forever on both sides", "Hot water bottles only, and no antibiotics"]'::jsonb, 0, 'Milk drainage helps resolution.', 'PON 416 · General Surgery'),
(3, 20, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'Free air under the diaphragm on an erect chest X-ray after a sudden abdominal pain suggests:', '["Perforated hollow viscus", "Pneumonia", "Normal finding", "Intestinal obstruction only"]'::jsonb, 0, 'Normal after recent laparotomy, otherwise needs urgent surgery.', 'PON 416 · General Surgery'),
(3, 21, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'A patient with a new colostomy is taught that a normal stoma:', '["Should look dry and pale when healthy, and feel painful to touch", "Should be painful whenever it is touched", "Bleeds heavily every time it is cleaned", "Has no nerve endings, so it does not feel pain"]'::jsonb, 3, 'Slight bleeding on cleaning is common.', 'PON 416 · General Surgery'),
(3, 22, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'Post-operative paralytic ileus is helped by:', '["Very high potassium intake by mouth", "Strict bed rest for the first week", "Large regular doses of morphine and strict bed rest for a week", "Early mobilisation, normal electrolytes and fewer opioids"]'::jsonb, 3, 'Chewing gum may also help.', 'PON 416 · General Surgery'),
(3, 23, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'A patient s/p bowel resection has absent bowel sounds and distension. The nurse suspects:', '["Bowel obstruction", "Paralytic ileus", "Anastomotic leak", "Peritonitis"]'::jsonb, 1, 'Ileus is common post-op; bowel sounds are absent/hypoactive.', 'PON 416 · General Surgery'),
(3, 24, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'A wound haematoma after surgery presents as:', '["A swollen, bruised, tender area under the wound", "A clean, dry, healing wound", "A small dry scab on the wound", "Pus with a foul smell only, and no swelling at all"]'::jsonb, 0, 'Large haematomas may need evacuation.', 'PON 416 · General Surgery'),
(3, 25, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'Before thyroid surgery, a patient''s voice is checked by laryngoscopy mainly to:', '["Measure the neck size so the correct collar is ready after surgery", "Check for dental caries before intubation", "Record vocal cord function before possible nerve injury", "Assess hearing before the anaesthetic"]'::jsonb, 2, 'Recurrent laryngeal nerve injury causes hoarseness.', 'PON 416 · General Surgery'),
(3, 26, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'Peritonitis can occur as a complication of:', '["Peptic ulcer disease", "Multiple organ failure", "Hypovolemic shock", "Septicemia"]'::jsonb, 0, 'Perforated peptic ulcer disease is a classic cause of secondary peritonitis.', 'PON 416 · General Surgery'),
(3, 27, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'A sebaceous (epidermoid) cyst is best treated by:', '["Antibiotics alone for two weeks", "Squeezing out the contents by hand", "Radiotherapy to the cyst area to shrink the lump", "Complete excision, including the cyst wall"]'::jsonb, 3, 'If the wall remains, the cyst can recur.', 'PON 416 · General Surgery'),
(3, 28, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'Gallstone ileus occurs when:', '["The pancreas becomes inflamed by alcohol and blocks the duodenum", "A large gallstone passes into the bowel and blocks it", "The gallbladder ruptures into the chest cavity", "Bile leaks into the abdomen after surgery"]'::jsonb, 1, 'Air in the biliary tree may be seen on imaging.', 'PON 416 · General Surgery'),
(3, 29, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'A right hemicolectomy is performed for cancer of the:', '["Sigmoid colon", "Rectum and anal canal", "Anal canal", "Caecum or ascending colon"]'::jsonb, 3, 'The ileum is joined to the transverse colon.', 'PON 416 · General Surgery'),
(3, 30, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'After an open inguinal hernia repair, the patient is advised to:', '["Avoid heavy lifting for about 4–6 weeks", "Stay on strict bed rest for 2 weeks", "Do sit-ups from the first day after surgery", "Avoid walking at all for about a month"]'::jsonb, 0, 'Early walking is encouraged; straining is avoided.', 'PON 416 · General Surgery'),
(3, 31, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'Before discharge after a mastectomy, the nurse teaches arm exercises mainly to:', '["Prevent shoulder stiffness and aid lymph drainage", "Increase the size of the chest muscles", "Reduce appetite and help weight loss after surgery", "Prevent wound infection at the drain site"]'::jsonb, 0, 'Start gently as advised by the surgeon.', 'PON 416 · General Surgery'),
(3, 32, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'A parastomal hernia is best prevented by:', '["Drinking much less water each day to reduce stoma output", "Changing the stoma bag every hour", "Avoiding heavy lifting and using a support belt", "Doing heavy weight training early"]'::jsonb, 2, 'It is a common late stoma complication.', 'PON 416 · General Surgery'),
(3, 33, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'A strangulated small bowel obstruction is suggested by:', '["Passing flatus normally with good bowel sounds", "Colicky pain that settles quickly with rest", "Normal heart rate and a soft, non-tender abdomen", "Constant pain, fever, tachycardia and peritonism"]'::jsonb, 3, 'It needs urgent surgery.', 'PON 416 · General Surgery'),
(3, 34, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'Triple assessment of a breast lump includes clinical examination, imaging and:', '["Tissue biopsy (core biopsy or FNA)", "A chest X-ray and blood tests for tumour markers only", "A random blood glucose test", "An ECG and echocardiogram"]'::jsonb, 0, 'All three are needed for an accurate diagnosis.', 'PON 416 · General Surgery'),
(3, 35, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'Damage control laparotomy in major trauma involves:', '["Completing all repairs in one long operation at once", "Avoiding surgery altogether and giving antibiotics", "Quick control of bleeding and contamination, with repair later", "Only giving IV fluids until the bleeding stops on its own, with no surgery"]'::jsonb, 2, 'The aim is to avoid the lethal triad.', 'PON 416 · General Surgery'),
(3, 36, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'Which of the following conditions is most likely to directly cause peritonitis?', '["Incarcerated hernia", "Cholelithiasis", "Perforated ulcer", "Gastritis"]'::jsonb, 2, 'A perforated ulcer spills GI contents directly into the peritoneal cavity, directly causing peritonitis.', 'PON 416 · General Surgery'),
(3, 37, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'Gastric outlet obstruction from pyloric stenosis in an adult typically causes:', '["Projectile vomiting of food and hypochloraemic alkalosis", "Bloody diarrhoea and high fever with abdominal cramps", "Jaundice and dark urine with pale stools and itching of the skin", "Constipation with no vomiting and normal electrolytes"]'::jsonb, 0, 'A succussion splash may be heard.', 'PON 416 · General Surgery'),
(3, 38, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'Rubber band ligation is a treatment for:', '["Pilonidal sinus", "Anal fissure", "External thrombosed piles", "Internal haemorrhoids"]'::jsonb, 3, 'Bands cut off blood supply so the pile falls off.', 'PON 416 · General Surgery'),
(3, 39, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'After liver resection, the nurse monitors closely for:', '["Bleeding, bile leak and liver failure", "Only blood pressure, every hour", "Only the colour of the urine and the time of the first bowel action", "Only wound pain, on a 0–10 scale"]'::jsonb, 0, 'Hypoglycaemia may occur because of reduced liver function.', 'PON 416 · General Surgery'),
(3, 40, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 416 · General Surgery', 'Bowel preparation before colonoscopy or some colorectal surgery mainly aims to:', '["Sterilise the bowel completely", "Treat anaemia", "Increase the patient''s weight", "Empty the colon of faeces"]'::jsonb, 3, 'Watch for dehydration and electrolyte loss.', 'PON 416 · General Surgery'),
(3, 41, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'After total hip replacement, sudden severe hip pain with leg shortening and rotation suggests:', '["Dislocation of the prosthesis", "Superficial wound infection", "Deep vein thrombosis in the operated leg", "Normal recovery after surgery"]'::jsonb, 0, 'Report immediately; closed reduction may be needed.', 'PON 417 · Trauma & Orthopaedics'),
(3, 42, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'After reduction of a dislocated shoulder, the arm is:', '["Placed in skeletal traction for two weeks", "Rested in a sling, with the axillary nerve checked", "Exercised fully at once to prevent stiffness", "Left without any support after reduction, to keep the joint mobile"]'::jsonb, 1, 'Recurrence is common in young patients.', 'PON 417 · Trauma & Orthopaedics'),
(3, 43, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Osteosarcoma most commonly affects:', '["Elderly people, in the skull", "Infants, in the hands", "Adolescents, around the knee", "Adults over 70 only, in the spine"]'::jsonb, 2, 'It is the most common primary bone cancer in young people.', 'PON 417 · Trauma & Orthopaedics'),
(3, 44, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A patient with a long leg cast is taught to report:', '["A slight warm feeling as it dries", "Needing help with walking aids", "Mild itching under the cast during the first few days", "Numbness, tingling, blue toes or worse pain"]'::jsonb, 3, 'These may indicate compartment syndrome or nerve compression.', 'PON 417 · Trauma & Orthopaedics'),
(3, 45, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A displaced intracapsular neck of femur fracture in an elderly patient is usually treated by:', '["Physiotherapy alone, without surgery", "Skin traction only for 3 months", "Hemiarthroplasty or total hip replacement", "A plaster cast for 6 weeks followed by walking on the leg"]'::jsonb, 2, 'The blood supply to the femoral head is often disrupted.', 'PON 417 · Trauma & Orthopaedics'),
(3, 46, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Bone cement implantation syndrome during joint replacement causes:', '["Joint stiffness only, after some months", "Fever starting about 3 days after surgery", "Slow wound healing over several weeks after the operation", "Sudden hypotension, hypoxia and possible arrest"]'::jsonb, 3, 'It occurs at the time of cementing and reaming.', 'PON 417 · Trauma & Orthopaedics'),
(3, 47, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A fractured clavicle is usually treated with:', '["Plaster of the chest", "Skeletal traction through the humerus", "Immediate surgery in all cases", "A broad arm sling and analgesia"]'::jsonb, 3, 'Most heal well without surgery.', 'PON 417 · Trauma & Orthopaedics'),
(3, 48, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Initial wound care for an open fracture in the emergency department includes:', '["Removing gross dirt, photographing and applying a moist sterile dressing", "Leaving the wound uncovered so it can dry out, and closing it with sutures", "Scrubbing deeply into the wound with a brush and soap", "Closing the wound with sutures to stop the bleeding"]'::jsonb, 0, 'Formal debridement is done in theatre.', 'PON 417 · Trauma & Orthopaedics'),
(3, 49, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Countertraction in a traction system is usually provided by:', '["The patient''s own body weight", "Extra weights hung on the head", "Tying the patient to the bed", "Removing the weights at night"]'::jsonb, 0, 'Without countertraction the patient slides down the bed.', 'PON 417 · Trauma & Orthopaedics'),
(3, 50, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Phantom limb pain after amputation is:', '["Pain caused only by tight bandages", "A real pain felt in the missing limb", "A sign of stump infection only, needing antibiotics", "Imagined pain that should be ignored"]'::jsonb, 1, 'Treatments include neuropathic analgesics and mirror therapy.', 'PON 417 · Trauma & Orthopaedics'),
(3, 51, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Crush syndrome after prolonged compression of a limb causes:', '["Bradycardia only, from vagal stimulation", "Hypertension only, caused by pain and anxiety after release", "Hypoglycaemia only, from muscle breakdown", "Hyperkalaemia, myoglobinuria and kidney injury"]'::jsonb, 3, 'Give IV fluids before releasing compression if possible.', 'PON 417 · Trauma & Orthopaedics'),
(3, 52, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Fibreglass casts compared with plaster of Paris:', '["Are heavier and take days to dry fully", "Cannot get wet at all, even when set, and take days to harden", "Are lighter and stronger, and dry faster", "Cannot be used for any type of fracture"]'::jsonb, 2, 'They are more expensive.', 'PON 417 · Trauma & Orthopaedics'),
(3, 53, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A Thomas splint needs care to prevent:', '["Wound infection of the hand on the same side", "Hypothermia of the whole leg", "Pressure sores at the groin ring", "Hearing loss from the weights"]'::jsonb, 2, 'Check and clean the skin under the ring.', 'PON 417 · Trauma & Orthopaedics'),
(3, 54, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'An external fixator is especially useful for:', '["Simple greenstick fractures", "Open fractures with soft tissue damage", "Depressed skull fractures in young children", "Small finger fractures only"]'::jsonb, 1, 'Pins pass through skin into bone and connect to an external frame.', 'PON 417 · Trauma & Orthopaedics'),
(3, 55, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Malunion of a fracture means:', '["The bone healed in perfect position", "The bone has healed in a poor position", "The bone has not healed at all after many months", "The bone healed much too quickly"]'::jsonb, 1, 'Non-union is failure to heal.', 'PON 417 · Trauma & Orthopaedics'),
(3, 56, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A patient with an acute gout attack has:', '["Painless joint swelling in both knees that comes on over many months", "A hot, red, very painful joint, often the big toe", "Stiffness only in the morning for an hour", "Joint pain that improves after alcohol"]'::jsonb, 1, 'It is due to uric acid crystal deposition.', 'PON 417 · Trauma & Orthopaedics'),
(3, 57, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Gallows (Bryant''s) traction is used for:', '["Spinal fractures in adults and the elderly", "Wrist fractures in elderly osteoporotic women", "Neck fractures after diving accidents in teenagers", "Femoral fractures in children under about 2 years"]'::jsonb, 3, 'The buttocks must be just clear of the bed.', 'PON 417 · Trauma & Orthopaedics'),
(3, 58, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A comminuted fracture is one in which:', '["A tendon pulls off a small piece of bone", "The bone is broken into more than two pieces", "The bone is bent but not fully broken through", "The skin is broken over the fracture site"]'::jsonb, 1, 'Avulsion fractures are where a tendon or ligament pulls off bone.', 'PON 417 · Trauma & Orthopaedics'),
(3, 59, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'When measuring axillary crutches, the nurse ensures there is:', '["Direct pressure of the pad firmly into the axilla when standing", "A gap of 2–3 finger widths below the axilla", "Elbows locked fully straight when walking", "The crutch top reaching up to the shoulder"]'::jsonb, 1, 'Pressure in the axilla can damage the radial nerve.', 'PON 417 · Trauma & Orthopaedics'),
(3, 60, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'ARDS in the context of orthopaedic trauma most often develops as a complication of:', '["Simple plaster cast application", "Fat embolism or severe polytrauma", "Routine elective joint replacement with no complications", "Isolated finger fractures"]'::jsonb, 1, 'Severe systemic insults like fat embolism or major polytrauma can trigger widespread lung inflammation, leading to ARDS.', 'PON 417 · Trauma & Orthopaedics'),
(3, 61, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A fracture of the humeral shaft may injure the radial nerve, causing:', '["Claw hand", "Facial palsy", "Wrist drop", "Foot drop"]'::jsonb, 2, 'Check wrist and finger extension.', 'PON 417 · Trauma & Orthopaedics'),
(3, 62, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'The ''golden period'' for debridement of an open fracture in theatre is generally within:', '["1 month", "1 week", "24 hours", "2 weeks"]'::jsonb, 2, 'Earlier debridement reduces infection.', 'PON 417 · Trauma & Orthopaedics'),
(3, 63, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'A patient with an itchy plaster cast should be told to:', '["Avoid pushing objects down the cast", "Pour water inside the cast", "Remove the cast at home if the itching becomes bad", "Use a knitting needle to scratch"]'::jsonb, 0, 'Objects can break the skin and cause infection.', 'PON 417 · Trauma & Orthopaedics'),
(3, 64, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'The Gustilo-Anderson classification grades:', '["Open fractures by wound and soft-tissue damage", "Spinal cord injuries by level and severity", "Burns by depth and percentage of body area", "Joint dislocations by direction, cause and nerve damage"]'::jsonb, 0, 'Grade III has the worst prognosis.', 'PON 417 · Trauma & Orthopaedics'),
(3, 65, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Blood at the urethral meatus after pelvic fracture means the nurse should NOT:', '["Check the pelvis on an X-ray film before giving analgesia", "Insert a urethral catheter before injury is excluded", "Give the patient analgesia for the pain", "Record the vital signs every 15 minutes"]'::jsonb, 1, 'A retrograde urethrogram may be needed.', 'PON 417 · Trauma & Orthopaedics'),
(3, 66, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Cast syndrome after a body cast (hip spica) is caused by:', '["An allergy to the plaster material", "Compression of the duodenum by an artery", "Too much fluid intake by mouth while lying in the cast", "Cold weather and low room temperature"]'::jsonb, 1, 'It causes vomiting and abdominal distension.', 'PON 417 · Trauma & Orthopaedics'),
(3, 67, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Buck''s skin traction is commonly used:', '["For skull traction after cervical spine injury", "Short-term before hip fracture surgery to ease pain", "For long-term treatment of spine fractures in adults", "For arm fractures only, in elderly patients"]'::jsonb, 1, 'Check the skin and heels regularly.', 'PON 417 · Trauma & Orthopaedics'),
(3, 68, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'Septic arthritis of the knee is treated urgently with:', '["Oral painkillers and rest", "Steroid injection into the joint", "Physiotherapy only", "Joint washout and IV antibiotics"]'::jsonb, 3, 'Cartilage can be destroyed within days.', 'PON 417 · Trauma & Orthopaedics'),
(3, 69, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'The initial management of an acute ankle sprain follows:', '["Immediate surgery for all sprains", "Heat, massage and early running", "Rest, ice, compression and elevation", "Long-term plaster for 3 months and complete bed rest"]'::jsonb, 2, 'Protect the joint and give analgesia.', 'PON 417 · Trauma & Orthopaedics'),
(3, 70, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 417 · Trauma & Orthopaedics', 'It Is the most common cause of pulmonary embolism.', '["Deep venous thrombosis", "Air bubbles", "Fat embolism", "Amniotic fluid embolus"]'::jsonb, 0, 'Deep venous thrombosis is by far the most common source of pulmonary embolism.', 'PON 417 · Trauma & Orthopaedics'),
(3, 71, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'A nurse preparing a woman for a dilatation and curettage should ensure:', '["Heavy meal before surgery", "A full bladder and supine position", "Consent, an empty bladder and the lithotomy position safely applied", "No consent is needed because it is a minor procedure done under sedation"]'::jsonb, 2, 'Lift both legs together into the stirrups.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 72, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Symphysiotomy is a procedure that:', '["Ties the fallopian tubes", "Removes the uterus and cervix through a vaginal approach", "Divides the pubic symphysis to enlarge the pelvis in obstructed labour", "Repairs a third-degree tear"]'::jsonb, 2, 'It is rarely used where caesarean section is not possible.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 73, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Red degeneration of a fibroid in pregnancy causes:', '["Acute abdominal pain over the fibroid with low-grade fever", "Jaundice and itching with dark urine", "Painless heavy bleeding", "Visual loss"]'::jsonb, 0, 'It is treated conservatively with analgesia.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 74, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'A cystocele is repaired by:', '["Anterior colporrhaphy (anterior vaginal repair)", "Myomectomy through a lower abdominal incision", "Cervical cerclage", "Posterior colporrhaphy"]'::jsonb, 0, 'A rectocele is repaired by posterior repair.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 75, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'This describe a condition where the fertilized egg implants itself in an area outside of the uterus.', '["Molar pregnancy", "Premolar pregnancy", "Hydatidiform mole", "Ectopic pregnancy"]'::jsonb, 3, 'A fertilised egg implanting outside the uterus is an ectopic pregnancy.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 76, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Endometritis after caesarean section presents with:', '["Leg swelling only", "Breast pain only, from engorgement", "Fever, uterine tenderness and offensive lochia", "Painless bleeding only"]'::jsonb, 2, 'Treat with antibiotics.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 77, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Acute uterine inversion should be treated by:', '["Pulling harder on the cord", "Waiting for 24 hours to see if the uterus returns on its own", "Immediate manual replacement of the uterus and treating shock", "Giving oxytocin before replacement"]'::jsonb, 2, 'Uterotonics are given only after the uterus is replaced.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 78, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'An inevitable miscarriage is one in which:', '["All products have passed and bleeding has stopped", "Bleeding occurs but the os is closed and the fetus alive", "Bleeding occurs and the cervical os is open", "The fetus has died but no bleeding occurs"]'::jsonb, 2, 'A threatened miscarriage has a closed os.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 79, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Mediolateral episiotomy is preferred over midline in many units because it:', '["Heals faster with no pain", "Lowers the risk of extension into the anal sphincter", "Is easier to perform", "Never needs any repair and heals without stitches"]'::jsonb, 1, 'Cut at about 60 degrees from the midline at crowning.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 80, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Vaginal bleeding after 28 weeks of pregnancy which is sudden in onset, painless, causeless and recurrent is known as.', '["Placenta praevia", "Vasa praevia", "Abruption placentae", "Abortion"]'::jsonb, 0, 'Sudden, painless, recurrent bleeding after 28 weeks is the classic description of placenta praevia.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 81, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'The main cause of cervical cancer is persistent infection with:', '["Herpes simplex virus", "Candida albicans (thrush) infection", "Human papillomavirus (HPV)", "Hepatitis B virus"]'::jsonb, 2, 'HPV vaccination and screening prevent most cases.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 82, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'When umbilical cord prolapse occurs, the woman should be placed in:', '["Standing upright or walking about while the theatre is prepared", "Sitting upright", "Supine with legs flat", "Knee-chest or exaggerated Sims position while preparing for urgent delivery"]'::jsonb, 3, 'Avoid handling the cord; fill the bladder if delay is expected.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 83, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Non-urgent surgery during pregnancy is safest in the:', '["Third trimester", "First trimester", "Second trimester", "Last week of pregnancy"]'::jsonb, 2, 'Organ formation is complete and preterm labour risk is lower.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 84, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'A woman with severe pre-eclampsia needs caesarean section. Spinal anaesthesia is generally preferred if:', '["She has very low platelets", "The platelet count is adequate (e.g. above 75–80 × 10⁹/L)", "She has no IV access and cannot have a cannula inserted", "She has a coagulopathy"]'::jsonb, 1, 'Low platelets increase the risk of spinal haematoma.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 85, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Among the 4 Ts of PPH, ''Tissue'' refers to:', '["Uterine muscle tone", "Retained placental tissue", "Genital tract lacerations", "Clotting factor deficiency"]'::jsonb, 1, 'Retained fragments of placenta or membranes prevent the uterus from contracting down fully, causing ongoing bleeding.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 86, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'A category 1 caesarean section (immediate threat to life of mother or baby) should ideally deliver the baby within:', '["30 minutes of the decision", "The next elective list, within 24 hours", "4 hours of the decision", "24 hours of the decision"]'::jsonb, 0, 'Category 2 targets within 75 minutes.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 87, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Massive obstetric haemorrhage protocols mainly aim to:', '["Avoid calling senior staff", "Delay transfusion until the laboratory confirms the haemoglobin level", "Rapidly deliver blood products and coordinate the team", "Wait for laboratory results before acting"]'::jsonb, 2, 'Communication with the blood bank is vital.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 88, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Total abdominal hysterectomy with bilateral salpingo-oophorectomy (TAH-BSO) in a premenopausal woman will cause:', '["No hormonal change", "Surgical menopause", "Increased fertility", "Weight loss"]'::jsonb, 1, 'Hormone replacement may be discussed.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 89, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'At caesarean section, oxytocin after delivery of the baby is given:', '["Orally after surgery, as an IV dose is unsafe in all women", "As a slow IV bolus (e.g. 5 IU), as rapid bolus can cause hypotension", "Only if the mother asks for it", "As a rapid 50 IU push"]'::jsonb, 1, 'Carbetocin is an alternative long-acting option.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 90, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Ectopic pregnancy can be confirmed by', '["Ultrasound", "Pregnancy test", "Laparoscopy", "HSG"]'::jsonb, 0, 'Ultrasound is the standard confirmatory imaging test for ectopic pregnancy.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 91, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'During caesarean section, the bladder is protected by:', '["Emptying it with a catheter and reflecting it down", "Placing the patient prone", "Ignoring it, as it cannot be injured", "Filling it with saline so it is easier to see"]'::jsonb, 0, 'Bladder injury is more common with repeat sections.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 92, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Bimanual uterine compression is used to:', '["Deliver the placenta", "Control haemorrhage from uterine atony", "Turn a breech baby", "Close the cervix after delivery of the placenta"]'::jsonb, 1, 'Combine with uterotonic drugs while preparing for theatre.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 93, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Primary postpartum haemorrhage after a vaginal delivery is defined as blood loss of:', '["≥2000ml", "≥1000ml", "≥200ml", "≥500ml"]'::jsonb, 3, '500ml or more within 24 hours of vaginal delivery meets the definition of primary PPH.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 94, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'A patient with postpartum haemorrhage has a soft, boggy uterus on palpation. The most likely cause, according to the ''4 Ts'' framework, is:', '["Thrombin (coagulopathy)", "Trauma", "Tissue (retained placenta)", "Tone (uterine atony)"]'::jsonb, 3, 'A soft, boggy (atonic) uterus is the classic finding of uterine atony (''Tone''), the most common cause of postpartum haemorrhage.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 95, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Management of uterine rupture is one of the following', '["Taking of history", "oxytocin should be administered", "Simple repair", "Uterine relaxation with tocolytic"]'::jsonb, 2, 'Simple surgical repair is the standard management approach for uterine rupture.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 96, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Anaemia before caesarean section is important because:', '["It has no effect on outcome", "It reduces the woman''s tolerance to blood loss", "It prevents bleeding", "It speeds wound healing and reduces infection"]'::jsonb, 1, 'Treat anaemia during pregnancy with iron.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 97, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'After vaginal hysterectomy, the nurse should monitor for:', '["Wrist pain and swelling from the IV cannula", "Facial swelling", "Vaginal bleeding and urinary retention", "Hearing loss"]'::jsonb, 2, 'A vaginal pack and catheter may be in place.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 98, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Secondary postpartum haemorrhage occurs within what timeframe after delivery?', '["First 24 hours only", "Only after 3 months", "Only in the first hour", "Day 1 up to 6 weeks postpartum"]'::jsonb, 3, 'Unlike primary PPH (within 24 hours), secondary PPH can occur any time from day 1 up to 6 weeks after birth.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 99, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'A woman with placenta praevia and a previous caesarean scar is at high risk of:', '["Ectopic pregnancy in the old caesarean scar only", "Polyhydramnios only", "Hyperemesis gravidarum", "Placenta accreta spectrum with massive haemorrhage"]'::jsonb, 3, 'Plan delivery in a centre with blood bank and senior surgeons.', 'PON 421 · Obstetric & Gynaecological Surgery'),
(3, 100, 'Perioperative Mock — Day 5 Night (Nov 2026)', 'PON 421 · Obstetric & Gynaecological Surgery', 'Medical treatment of an unruptured ectopic pregnancy with stable vital signs and low hCG may use:', '["Magnesium sulfate", "Oxytocin", "Misoprostol alone", "Methotrexate"]'::jsonb, 3, 'Serial hCG levels are followed until negative.', 'PON 421 · Obstetric & Gynaecological Surgery');
